{"path":"index.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>{{BUSINESS_NAME}} — A practical, whole-life path</title>
  <meta name="description" content="Holistic care shaped around everyday rhythm — clear steps, visible timeline, and thoughtful guidance.">
  <link rel="stylesheet" href="assets/css/styles.css">
  <script defer src="assets/js/main.js"></script>
</head>
<body class="page-root">
  <header class="site-header">
    <div class="container header-inner">
      <a class="brand" href="/">{{BUSINESS_NAME}}</a>
      <nav class="nav" aria-label="Main navigation">
        <a href="/services.html">Offerings</a>
        <a href="/conditions.html">Ailments</a>
        <a href="/approach.html">Method</a>
        <a href="/pricing.html">Investment</a>
        <a href="/about.html">Who we are</a>
        <a class="btn-ghost" href="/book.html">Reserve</a>
        <a class="btn-primary" href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a>
      </nav>
    </div>
  </header>

  <main>
    <section class="hero">
      <div class="pattern"></div>
      <div class="container hero-inner">
        <div class="hero-copy">
          <p class="eyebrow">Personalized care with measured steps</p>
          <h1>Design your steady-change plan with clear phases</h1>
          <p class="lead">We map sensible shifts across mind, movement, and nourishment so you can test what works and keep the wins.</p>
          <div class="hero-ctas">
            <a class="btn-primary" href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a>
            <a class="btn-link" href="/about.html">Learn about our approach</a>
          </div>
        </div>
        <aside class="hero-aside">
          <div class="card contact-card">
            <strong>Quick connect</strong>
            <p>{{CITY}}, {{STATE}}</p>
            <a href="tel:{{PHONE}}">Call: {{PHONE}}</a>
            <a href="mailto:{{EMAIL}}">Email: {{EMAIL}}</a>
          </div>
        </aside>
      </div>
    </section>

    <section class="story container" id="story">
      <div class="story-grid">
        <div>
          <h2>A practical philosophy</h2>
          <p>We translate whole-person thinking into small, testable actions. Our intent is to make shifts measurable and teach you how to maintain them between sessions.</p>
          <ul>
            <li>Co-created plans, not one-size tactics</li>
            <li>Emphasis on daily rhythms and simple signals</li>
            <li>Education-forward, evidence-aware conversations</li>
          </ul>
        </div>
        <div>
          <h3>Who this is for</h3>
          <p>People ready to try tiered, tangible changes rather than quick fixes. We support self-directed care with professional guidance.</p>
        </div>
      </div>
    </section>

    <section class="framework" id="framework">
      <div class="container">
        <h2>Roadmap Planner</h2>
        <p class="muted">Pick three phases and allocate weeks to see the flow. This visual helps keep momentum and clarify what we're testing.</p>

        <div class="planner">
          <div class="phases">
            <div class="phase" data-phase="1">
              <label>Phase 1 — Stabilize</label>
              <input type="number" class="weeks" min="1" max="12" value="2" data-phase="1"> weeks
              <p class="small">Short-term priorities and baseline measures.</p>
            </div>
            <div class="phase" data-phase="2">
              <label>Phase 2 — Adjust</label>
              <input type="number" class="weeks" min="1" max="16" value="4" data-phase="2"> weeks
              <p class="small">Introduce or adapt elements and track reactions.</p>
            </div>
            <div class="phase" data-phase="3">
              <label>Phase 3 — Integrate</label>
              <input type="number" class="weeks" min="2" max="24" value="8" data-phase="3"> weeks
              <p class="small">Sustain successful changes and plan next steps.</p>
            </div>
          </div>

          <div class="timeline-visual" aria-hidden="true">
            <div class="timeline-bar" id="timelineBar"></div>
            <div class="timeline-labels" id="timelineLabels"></div>
          </div>

          <div class="disclaimer">
            <strong>Note</strong>
            <p>These phases are planning tools and educational in nature. They are not a substitute for medical diagnosis. Always discuss medication changes or serious symptoms with your licensed provider.</p>
          </div>
        </div>
      </div>
    </section>

    <section class="offers container" id="offers">
      <h2>Signature Sessions</h2>
      <p class="muted">A la carte options and focused day experiences to jumpstart change.</p>
      <div class="offer-grid">
        <article class="offer-card">
          <h3>Clarity Day</h3>
          <p class="price">Single immersive session</p>
          <p>One-day strategic review with a tailored short plan and take-home resources.</p>
          <a class="btn-outline" href="/book.html">Reserve a Clarity Day</a>
        </article>
        <article class="offer-card">
          <h3>Momentum Trio</h3>
          <p class="price">Three-session focused pathway</p>
          <p>Three guided visits across phases to test and adapt practical steps.</p>
          <a class="btn-outline" href="/book.html">Start the Momentum Trio</a>
        </article>
        <article class="offer-card">
          <h3>Quarter Care Plan</h3>
          <p class="price">12-week guided rhythm plan</p>
          <p>Structured sequence, check-ins, and resources for steady progress.</p>
          <a class="btn-outline" href="/book.html">Explore the Quarter Plan</a>
        </article>
      </div>
    </section>

    <section class="pricing container" id="pricing">
      <h2>Investment framing</h2>
      <p class="muted">Transparent options and what they help you accomplish.</p>
      <div class="pricing-cards">
        <div class="pricing-card">
          <h3>Starter Check</h3>
          <p class="amount">$295</p>
          <p>One session for assessment and short-term planning.</p>
        </div>
        <div class="pricing-card featured">
          <h3>Focused Path</h3>
          <p class="amount">$895</p>
          <p>Three sessions to stabilize, refine, and integrate practices.</p>
        </div>
        <div class="pricing-card">
          <h3>Quarter Program</h3>
          <p class="amount">$2200</p>
          <p>Twelve-week guided program with resources and check-ins.</p>
        </div>
      </div>
      <p class="muted small">All options include educational materials. No guaranteed cures; care is supportive and individualized.</p>
    </section>

    <section class="testimonials container" id="testimonials">
      <h2>Proof Gallery</h2>
      <p class="muted">Selected notes from people we've supported and a snapshot of credentials on our wall.</p>

      <div class="proof">
        <div class="testimonial">
          <blockquote id="testimonialText">"A clear plan I could actually test in real life — small wins made a difference."</blockquote>
          <cite id="testimonialAuthor">— A client, Portland</cite>
          <div class="controls">
            <button id="prevTestimonial" aria-label="Previous testimonial">◀</button>
            <button id="nextTestimonial" aria-label="Next testimonial">▶</button>
          </div>
        </div>

        <aside class="credibility">
          <div class="badges" id="badges">
            <div class="badge" data-tooltip="Board-aligned training in integrative practice">Clinically Trained</div>
            <div class="badge" data-tooltip="Published case summaries and patient education">Published Guides</div>
            <div class="badge" data-tooltip="Member of local health collaboratives">Community Partner</div>
          </div>
          <p class="muted small">Testimonials are anonymized and represent individual experiences. Outcomes vary.</p>
        </aside>
      </div>
    </section>

    <section class="cta container" id="final-cta">
      <div class="cta-inner">
        <h2>Ready to try a different path?</h2>
        <p>Book an initial clarity conversation to sketch your first-phase plan.</p>
        <a class="btn-primary" href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a>
      </div>
    </section>
  </main>

  <footer class="site-footer">
    <div class="container footer-inner">
      <div>
        <strong>{{BUSINESS_NAME}}</strong>
        <p>{{CITY}}, {{STATE}}</p>
      </div>
      <nav class="footer-nav">
        <a href="/contact.html">Contact</a>
        <a href="/about.html">About</a>
        <a href="/services.html">Services</a>
      </nav>
      <div class="legal">
        <p class="small muted">Educational information only. Not medical advice. If you have urgent concerns, contact your medical provider.</p>
      </div>
    </div>
  </footer>
</body>
</html>"} 
