{"path":"assets/css/styles.css","content":":root{--bg:#fbfbfb;--accent:#3b7c6b;--muted:#6b6b6b;--card:#ffffff;--accent-2:#ffd166;--accent-3:#2d4059}
*{box-sizing:border-box}
html,body{height:100%}
body{font-family:system-ui,-apple-system,"Segoe UI",Roboto,Helvetica,Arial,sans-serif;margin:0;background:var(--bg);color:var(--accent-3);line-height:1.45}
.container{max-width:1100px;margin:0 auto;padding:28px}
.site-header{background:linear-gradient(180deg, rgba(59,124,107,0.06), transparent);border-bottom:1px solid rgba(0,0,0,0.04)}
.header-inner{display:flex;align-items:center;justify-content:space-between}
.brand{font-weight:700;color:var(--accent-3);text-decoration:none}
.nav a{margin-left:14px;color:var(--accent-3);text-decoration:none}
.btn-primary{background:var(--accent);color:#fff;padding:10px 14px;border-radius:8px;text-decoration:none;font-weight:700}
.btn-ghost{background:transparent;border:1px solid rgba(59,124,107,0.12);padding:8px 10px;border-radius:8px;text-decoration:none;color:var(--accent-3)}
.btn-outline{display:inline-block;margin-top:12px;padding:10px 12px;border-radius:8px;border:1px solid rgba(0,0,0,0.08);text-decoration:none;color:var(--accent-3)}
.hero{position:relative;overflow:hidden;padding:56px 0}
.pattern{position:absolute;inset:0;background-image:url('/assets/img/pattern.svg');opacity:0.06;background-repeat:repeat;background-size:220px}
.hero-inner{display:grid;grid-template-columns:1fr 320px;gap:28px;align-items:start}
.eyebrow{font-weight:700;color:var(--accent);text-transform:uppercase;margin:0}
h1{font-size:32px;margin:8px 0 12px}
.lead{color:var(--muted)}
.hero-aside .card{background:var(--card);padding:16px;border-radius:12px;box-shadow:0 6px 18px rgba(45,64,89,0.06)}
.story{padding-top:10px;padding-bottom:10px}
.story-grid{display:grid;grid-template-columns:1fr 320px;gap:20px}
.framework{background:linear-gradient(180deg,#fff,rgba(59,124,107,0.02));padding:36px 0;border-radius:10px;margin-top:18px}
.planner{display:grid;gap:18px}
.phases{display:flex;gap:16px}
.phase{background:var(--card);padding:12px;border-radius:10px;flex:1;border:1px solid rgba(0,0,0,0.04)}
.phase label{font-weight:700}
.phase input.weeks{width:60px;margin-left:8px}
.timeline-visual{background:transparent;padding:16px}
.timeline-bar{height:28px;background:linear-gradient(90deg,var(--accent) 0%, var(--accent-2) 60%, rgba(45,64,89,0.06) 100%);border-radius:8px;display:flex;overflow:hidden}
.timeline-seg{height:100%;display:flex;align-items:center;justify-content:center;color:#fff;font-weight:700}
.timeline-labels{display:flex;gap:8px;margin-top:8px}
.timeline-label{font-size:13px;color:var(--muted)}
.disclaimer{background:rgba(0,0,0,0.03);padding:12px;border-radius:8px}
.offers{padding:30px 0}
.offer-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:18px}
.offer-card{background:var(--card);padding:18px;border-radius:12px;border:1px solid rgba(0,0,0,0.04)}
.pricing{padding:20px 0}
.pricing-cards{display:flex;gap:14px}
.pricing-card{flex:1;background:var(--card);padding:16px;border-radius:10px;border:1px solid rgba(0,0,0,0.04);text-align:center}
.pricing-card.featured{transform:translateY(-6px);box-shadow:0 10px 30px rgba(45,64,89,0.06)}
.amount{font-weight:800;font-size:20px}
.testimonials{padding:30px 0}
.proof{display:flex;gap:20px;align-items:flex-start}
.testimonial{flex:1;background:var(--card);padding:18px;border-radius:12px}
.testimonial blockquote{margin:0;font-style:italic}
.controls{margin-top:12px}
.controls button{background:transparent;border:1px solid rgba(0,0,0,0.06);padding:6px 10px;border-radius:6px;margin-right:6px}
.credibility{width:260px}
.badges{display:flex;flex-direction:column;gap:8px}
.badge{background:linear-gradient(90deg,#fff,#f8f8f8);padding:8px;border-radius:8px;border-left:4px solid var(--accent);cursor:default}
.badge[data-tooltip]{position:relative}
.badge[data-tooltip]:hover::after{content:attr(data-tooltip);position:absolute;left:calc(100% + 8px);top:50%;transform:translateY(-50%);white-space:nowrap;background:#2d4059;color:#fff;padding:6px 10px;border-radius:6px;font-size:13px}
.cta{background:linear-gradient(90deg,rgba(59,124,107,0.06),transparent);padding:28px;border-radius:10px;margin:28px 0;text-align:center}
.site-footer{border-top:1px solid rgba(0,0,0,0.04);padding:20px 0;margin-top:30px}
.footer-inner{display:flex;align-items:center;justify-content:space-between}
.muted{color:var(--muted)}
.small{font-size:13px}
@media (max-width:900px){.hero-inner,.story-grid{grid-template-columns:1fr}.offer-grid{grid-template-columns:1fr}.pricing-cards{flex-direction:column}.proof{flex-direction:column}.credibility{width:100%}.badges{flex-direction:row}}
"} 
{"path":"assets/js/main.js","content":"document.addEventListener('DOMContentLoaded',function(){
  // Timeline planner logic
  const weekInputs = document.querySelectorAll('.phase input.weeks');
  const timelineBar = document.getElementById('timelineBar');
  const timelineLabels = document.getElementById('timelineLabels');

  function renderTimeline(){
    const values = Array.from(weekInputs).map(i=>Math.max(1,parseInt(i.value)||1));
    const total = values.reduce((a,b)=>a+b,0);
    timelineBar.innerHTML = '';
    timelineLabels.innerHTML = '';
    values.forEach((val,idx)=>{
      const pct = Math.round((val/total)*100);
      const seg = document.createElement('div');
      seg.className = 'timeline-seg';
      seg.style.flex = String(val);
      seg.style.background = `linear-gradient(90deg, rgba(59,124,107,${0.08*(idx+1)}), rgba(255,209,102,${0.03*(idx+1)}))`;
      seg.textContent = `${pct}%`;
      timelineBar.appendChild(seg);

      const lab = document.createElement('div');
      lab.className = 'timeline-label';
      lab.textContent = `Phase ${idx+1}: ${val}w`;
      timelineLabels.appendChild(lab);
    });
  }
  weekInputs.forEach(i=>i.addEventListener('input',renderTimeline));
  renderTimeline();

  // Proof Gallery logic
  const testimonials = [
    {text:'"I finally had a plan I could test and measure — the slow approach worked for me."',author:'— M., Seattle'},
    {text:'"Helpful education and real, sustainable small changes that fit my schedule."',author:'— K., Austin'},
    {text:'"A clear roadmap that felt flexible. We tracked simple signals and it changed how I made choices."',author:'— R., Denver'}
  ];
  let current = 0;
  const tText = document.getElementById('testimonialText');
  const tAuthor = document.getElementById('testimonialAuthor');
  const prevBtn = document.getElementById('prevTestimonial');
  const nextBtn = document.getElementById('nextTestimonial');

  function showTestimonial(i){
    current = (i+testimonials.length)%testimonials.length;
    tText.textContent = testimonials[current].text;
    tAuthor.textContent = testimonials[current].author;
  }
  prevBtn.addEventListener('click',()=>showTestimonial(current-1));
  nextBtn.addEventListener('click',()=>showTestimonial(current+1));
  let rotate = setInterval(()=>showTestimonial(current+1),6000);
  [prevBtn,nextBtn,tText].forEach(el=>el.addEventListener('mouseenter',()=>clearInterval(rotate)));
  [prevBtn,nextBtn,tText].forEach(el=>el.addEventListener('mouseleave',()=>rotate=setInterval(()=>showTestimonial(current+1),6000)));
  showTestimonial(0);

  // Badge tooltips accessible enhancement (keyboard)
  const badges = document.querySelectorAll('.badge[data-tooltip]');
  badges.forEach(b=>{
    b.setAttribute('tabindex','0');
    b.addEventListener('focus',()=>b.classList.add('focused'));
    b.addEventListener('blur',()=>b.classList.remove('focused'));
  });

  // Simple URL placeholder substitution for client-side preview (not required for server)
  function injectPlaceholders(){
    const holders = document.body.innerHTML.match(/{{[A-Z_]+}}/g) || [];
    holders.forEach(key=>{
      // leave placeholders in place; no default injection for privacy
    });
  }
  injectPlaceholders();
});"} 
